const rows = [];
function match(text, label) {
  const re = new RegExp(`(?:^|\n)\s*(?:${label})\s*[:\-|]\s*(.+)`, 'i');
  const m = text.match(re);
  return m ? m[1].split('\n')[0].replace(/\s*\|.*$/, '').trim() : '';
}
for (const item of items) {
  const src = item.json;
  const text = [src.textPlain, src.snippet, src.textHtml]
    .filter(Boolean).join('\n')
    .replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ');
  rows.push({ json: {
    source:            'google_form',
    external_id:       src.id || src.messageId,
    full_name:         match(text, 'Name'),
    email:             match(text, 'Email'),
    phone:             match(text, 'Phone|Mobile'),
    service_requested: match(text, 'Service|Service Requested|Job Description'),
    message:           match(text, 'Message|Comments|Details|Additional Information|Project Summary'),
    raw_payload:       src,
    received_at:       src.date || new Date().toISOString()
  }});
}
return rows;

