for (const item of items) {
  const src = item.json;
  const rawHtml = src.textHtml || '';
  const stripped = rawHtml
    .replace(/<br\s*\/?>/gi, '\n').replace(/<\/tr>/gi, '\n')
    .replace(/<\/td>/gi, ' | ').replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').trim();
  const text = [src.textPlain, src.snippet, stripped].filter(Boolean).join('\n');
  rows.push({ json: {
    source:            'same_day_home_services',
    external_id:       src.id || src.messageId,
    full_name:         match(text, 'Customer Name'),
    email:             match(text, 'Email'),
    phone:             match(text, 'Phone'),
    service_requested: match(text, 'Requested Service'),
    message:           match(text, 'Project Summary|Additional Information|Message|Comments|Details'),
    raw_payload:       src,
    received_at:       src.date || new Date().toISOString()
  }});
}
return rows;

